import java.util.Arrays;

public class ArraysDemo {
    public static void main(String[] args) {
        int[] data = {6, 7, 12, 5, 1, 2};

        System.out.println(Arrays.toString(data));    // [6, 7, 12, 5, 1, 2]
        Arrays.sort(data);
        System.out.println(Arrays.toString(data));    // [1, 2, 5, 6, 7, 12]
        System.out.println(Arrays.binarySearch(data, 6));   // 3

        int[] filled = new int[5];
        Arrays.fill(filled, 8);
        System.out.println(Arrays.toString(filled));  // [8, 8, 8, 8, 8]
    }
}
